# ================================================================================

def fitness_bmi_category(chromosome, target):
    weight, height = chromosome
    K = 1.0

    def bd_lt(left, right):
        val = left - right
        return 0.0 if val < 0 else val + K

    def bd_le(left, right):
        val = left - right
        return 0.0 if val <= 0 else val

    def bd_gt(left, right):
        val = right - left
        return 0.0 if val < 0 else val + K

    def bd_ge(left, right):
        val = right - left
        return 0.0 if val <= 0 else val

    if target == "invalid_height":
        return bd_le(height, 0.0)

    dist_height_gt_0 = bd_gt(height, 0.0)

    if target == "underweight":
        return dist_height_gt_0 + bd_lt(bmi_calc(weight, height), 18.5)

    if target == "normal":
        return dist_height_gt_0 + bd_ge(bmi_calc(weight, height), 18.5) + bd_lt(bmi_calc(weight, height), 25.0)

    if target == "overweight":
        return dist_height_gt_0 + bd_ge(bmi_calc(weight, height), 25.0) + bd_lt(bmi_calc(weight, height), 30.0)

    if target == "obese":
        return dist_height_gt_0 + bd_ge(bmi_calc(weight, height), 30.0)

    raise ValueError("Unknown target: " + target)

def bmi_calc(weight, height):
    # Replicate BMI calculation to avoid calling original function
    # Assume height > 0 due to previous branch distance checks
    return weight / (height * height)

