# Original function: number_kind
# Fitness function: fitness_number_kind
# LLM targets: ['zero', 'even', 'odd']
# Notes: The fitness function calculates the branch distance for three targets: 'zero', 'even', and 'odd'. For 'zero', it directly measures the distance to x == 0. For 'even', it combines distances to satisfy x != 0 and x % 2 == 0. For 'odd', it combines distances to satisfy x != 0 and x % 2 != 0. Helper functions normalize distances, ensuring 0.0 for satisfied conditions and positive values for unsatisfied conditions, with smaller values indicating closer proximity.
# ================================================================================

def normalize(v):
    if v == 0:
        return 0.0
    return 1.0 - (1.0 / (1.0 + v))

def branch_distance_eq(left, right):
    return normalize(abs(left - right))

def branch_distance_ne(left, right):
    if left == right:
        return 1.0
    return 0.0

def branch_distance_modulo_eq_zero(value, divisor):
    if divisor == 0:
        return 1.0
    return normalize(abs(value % divisor))

def branch_distance_modulo_ne_zero(value, divisor):
    if divisor == 0:
        return 0.0
    if value % divisor == 0:
        return 1.0
    return 0.0

def fitness_number_kind(chromosome, target):
    x = chromosome[0]

    if target == "zero":
        return branch_distance_eq(x, 0)
    elif target == "even":
        dist_x_not_zero = branch_distance_ne(x, 0)
        dist_x_mod_2_zero = branch_distance_modulo_eq_zero(x, 2)
        return dist_x_not_zero + dist_x_mod_2_zero
    elif target == "odd":
        dist_x_not_zero = branch_distance_ne(x, 0)
        dist_x_mod_2_not_zero = branch_distance_modulo_ne_zero(x, 2)
        return dist_x_not_zero + dist_x_mod_2_not_zero
    else:
        raise ValueError(f"Unknown target: {target}")

