# ================================================================================

TARGETS_pin_pattern = ["secret_pin", "all_same", "ordered_sum_20", "other"]

def fitness_pin_pattern(chromosome, target):
    a, b, c, d = chromosome[0], chromosome[1], chromosome[2], chromosome[3]

    # Helper functions for branch distance calculations
    def _cond_true_eq(left, right):
        return abs(left - right)

    def _cond_true_lt(left, right):
        # Distance to make 'left < right' true. If 'left >= right', distance is 'left - right + 1'.
        return max(0, left - right + 1)

    # Helper for 'elif' and 'else' conditions, penalizing if a prior condition was met
    def _cond_false_penalty(cond_true_fitness_val):
        # Returns a small positive penalty (1.0) if the condition was met (i.e., its fitness is 0).
        # Otherwise, returns 0, indicating the condition was not met.
        return 1.0 if cond_true_fitness_val == 0 else 0.0

    # --- Calculate fitness for each original condition to be TRUE ---

    # Condition 1: a == 7 and b == 3 and c == 9 and d == 1
    cond1_true_fitness = (
        _cond_true_eq(a, 7) +
        _cond_true_eq(b, 3) +
        _cond_true_eq(c, 9) +
        _cond_true_eq(d, 1)
    )

    # Condition 2: a == b == c == d (equivalent to a==b and b==c and c==d)
    cond2_true_fitness = (
        _cond_true_eq(a, b) +
        _cond_true_eq(b, c) +
        _cond_true_eq(c, d)
    )

    # Condition 3: a + b + c + d == 20 and a < b < c < d
    sum_abcd = a + b + c + d
    cond3_true_fitness = (
        _cond_true_eq(sum_abcd, 20) +
        _cond_true_lt(a, b) +
        _cond_true_lt(b, c) +
        _cond_true_lt(c, d)
    )

    # --- Assign fitness based on target ---
    if target == "secret_pin":
        return cond1_true_fitness
    elif target == "all_same":
        # To reach 'all_same', condition 1 must be false, and condition 2 must be true.
        return cond2_true_fitness + _cond_false_penalty(cond1_true_fitness)
    elif target == "ordered_sum_20":
        # To reach 'ordered_sum_20', condition 1 and 2 must be false, and condition 3 must be true.
        return (
            cond3_true_fitness +
            _cond_false_penalty(cond1_true_fitness) +
            _cond_false_penalty(cond2_true_fitness)
        )
    elif target == "other":
        # To reach 'other', all previous conditions must be false.
        return (
            _cond_false_penalty(cond1_true_fitness) +
            _cond_false_penalty(cond2_true_fitness) +
            _cond_false_penalty(cond3_true_fitness)
        )
    else:
        raise ValueError("Unknown target: " + target)

