def fitness_shipping_discount(chromosome, target):
    order_total, distance, is_member = chromosome

    def dist_true_lt(a, b):
        return max(0.0, a - b + 1.0)

    def dist_true_geq(a, b):
        return max(0.0, b - a + 0.0)

    def dist_true_leq(a, b):
        return max(0.0, a - b + 0.0)

    def dist_true_bool(b_val):
        return 0.0 if b_val else 1.0

    # Evaluate all conditions to determine the actual path taken by the input
    cond_path_invalid = (order_total < 0) or (distance < 0)
    cond_path_free_express = (order_total >= 200) and (distance <= 50) and is_member
    cond_path_standard = (order_total >= 100) and (distance <= 100)
    cond_path_small = (order_total >= 50) or is_member

    if target == "invalid":
        # Target: order_total < 0 or distance < 0
        d_ot_lt_0 = dist_true_lt(order_total, 0)
        d_dist_lt_0 = dist_true_lt(distance, 0)
        return min(d_ot_lt_0, d_dist_lt_0)

    elif target == "free_express_shipping":
        # Conditions: order_total >= 200 AND distance <= 50 AND is_member

        # Distances for the current branch's conditions
        d_ot_geq_200 = dist_true_geq(order_total, 200)
        d_dist_leq_50 = dist_true_leq(distance, 50)
        d_is_member = dist_true_bool(is_member)
        current_branch_distance = d_ot_geq_200 + d_dist_leq_50 + d_is_member
        
        # Penalize if higher priority branches would be taken
        if cond_path_invalid:
            return current_branch_distance + 1000.0
        
        return current_branch_distance

    elif target == "standard_discount":
        # Conditions: order_total >= 100 AND distance <= 100

        # Distances for the current branch's conditions
        d_ot_geq_100 = dist_true_geq(order_total, 100)
        d_dist_leq_100 = dist_true_leq(distance, 100)
        current_branch_distance = d_ot_geq_100 + d_dist_leq_100

        # Penalize if higher priority branches would be taken
        if cond_path_invalid:
            return current_branch_distance + 10000.0
        if cond_path_free_express:
            return current_branch_distance + 5000.0
        
        return current_branch_distance

    elif target == "small_discount":
        # Conditions: order_total >= 50 OR is_member

        # Distances for the current branch's conditions
        d_ot_geq_50 = dist_true_geq(order_total, 50)
        d_is_member = dist_true_bool(is_member)
        current_branch_distance = min(d_ot_geq_50, d_is_member)

        # Penalize if higher priority branches would be taken
        if cond_path_invalid:
            return current_branch_distance + 10000.0
        if cond_path_free_express:
            return current_branch_distance + 5000.0
        if cond_path_standard:
            return current_branch_distance + 2500.0
        
        return current_branch_distance

    elif target == "no_discount":
        # This target is reached if all preceding conditions are false

        # Penalize if higher priority branches would be taken
        if cond_path_invalid:
            return 10000.0
        if cond_path_free_express:
            return 5000.0
        if cond_path_standard:
            return 2500.0
        if cond_path_small:
            return 1250.0
        
        return 0.0 # Reached

