# Original function: string_category
# Fitness function: fitness_string_category
# LLM targets: ['empty', 'long_palindrome', 'short_palindrome', 'long_non_palindrome', 'other']
# Notes: Corrected the branch distance calculations for 'less than or equal to' conditions (e.g., len(s) <= 3 and len(s) <= 5) by introducing 'le_dist' helper function. Previously, the negation of 'greater than' was incorrectly using 'ge_dist' with inverted logic, leading to semantic mismatches.
# ================================================================================

TARGETS_string_category = ["empty", "long_palindrome", "short_palindrome", "long_non_palindrome", "other"]

def fitness_string_category(chromosome, target):
    s = chromosome[0]
    s_rev = s[::-1]
    len_s = len(s)

    # Helper functions for branch distance calculations
    def eq_dist(val, target_val):
        return abs(val - target_val)

    def gt_dist(val, threshold):
        # Distance to satisfy val > threshold (i.e., val >= threshold + 1)
        return max(0, (threshold + 1) - val)

    def ge_dist(val, threshold):
        # Distance to satisfy val >= threshold
        return max(0, threshold - val)

    def lt_dist(val, threshold):
        # Distance to satisfy val < threshold (i.e., val <= threshold - 1)
        return max(0, val - (threshold - 1))

    def le_dist(val, threshold):
        # Distance to satisfy val <= threshold
        return max(0, val - threshold)

    def str_pal_dist(s_actual, s_reversed):
        # Distance to satisfy s_actual == s_reversed
        if s_actual == s_reversed:
            return 0
        mismatches = 0
        # s_actual and s_reversed always have the same length
        for i in range(len(s_actual)):
            if s_actual[i] != s_reversed[i]:
                mismatches += 1
        return mismatches if mismatches > 0 else 1

    # Branch distances for conditions and their negations
    dist_len_s_eq_0_true = eq_dist(len_s, 0)
    dist_len_s_ne_0_true = gt_dist(len_s, 0) # equivalent to len_s > 0 or len_s >= 1

    dist_s_is_palindrome_true = str_pal_dist(s, s_rev)
    dist_s_is_not_palindrome_true = 0 if s != s_rev else 1 # 0 if s is not a palindrome, 1 if it is

    dist_len_s_gt_3_true = gt_dist(len_s, 3) # len(s) > 3 means len(s) >= 4
    dist_len_s_le_3_true = le_dist(len_s, 3) # len(s) <= 3

    dist_len_s_gt_5_true = gt_dist(len_s, 5) # len(s) > 5 means len(s) >= 6
    dist_len_s_le_5_true = le_dist(len_s, 5) # len(s) <= 5

    if target == "empty":
        # Path: len(s) == 0
        return dist_len_s_eq_0_true
    elif target == "long_palindrome":
        # Path: len(s) != 0 AND s == s[::-1] AND len(s) > 3
        return dist_len_s_ne_0_true + dist_s_is_palindrome_true + dist_len_s_gt_3_true
    elif target == "short_palindrome":
        # Path: len(s) != 0 AND s == s[::-1] AND NOT (len(s) > 3) --> len(s) <= 3
        return dist_len_s_ne_0_true + dist_s_is_palindrome_true + dist_len_s_le_3_true
    elif target == "long_non_palindrome":
        # Path: len(s) != 0 AND s != s[::-1] AND len(s) > 5
        return dist_len_s_ne_0_true + dist_s_is_not_palindrome_true + dist_len_s_gt_5_true
    elif target == "other":
        # Path: len(s) != 0 AND s != s[::-1] AND NOT (len(s) > 5) --> len(s) <= 5
        return dist_len_s_ne_0_true + dist_s_is_not_palindrome_true + dist_len_s_le_5_true
    else:
        raise ValueError("Unknown target")

